\SyntheticChild\\SyntheticLeaf[9]","startTime":"2026-01-01T00:00:00Z","endTime":"2026-01-01T00:00:01Z","durationMs":10,"executionResult":0},{"statisticsId":"5","executionId":"9007199254740993","executableId":"55","executableGuid":"33333333-3333-3333-3333-333333333333","packageName":"SyntheticRoot.dtsx","packagePath":"\\Package\\SyntheticLoop","executionPath":"\\SyntheticRoot\\SyntheticLoop","startTime":"2026-01-01T00:00:00Z","endTime":"2026-01-01T00:00:01Z","durationMs":10,"executionResult":0},{"statisticsId":"6","executionId":"9007199254740993","executableId":"56","executableGuid":"44444444-4444-4444-4444-444444444444","packageName":"SyntheticRoot.dtsx","packagePath":"\\Package\\SyntheticLoop\\SyntheticCall","executionPath":"\\SyntheticRoot\\SyntheticLoop[1]\\SyntheticCall","startTime":"2026-01-01T00:00:00Z","endTime":"2026-01-01T00:00:01Z","durationMs":10,"executionResult":0},{"statisticsId":"7","executionId":"9007199254740993","executableId":"57","executableGuid":"11111111-1111-1111-1111-111111111111","packageName":"SyntheticChild.dtsx","packagePath":"\\Package","executionPath":"\\SyntheticRoot\\SyntheticLoop[1]\\SyntheticCall\\SyntheticChild","startTime":"2026-01-01T00:00:00Z","endTime":"2026-01-01T00:00:01Z","durationMs":10,"executionResult":0},{"statisticsId":"8","executionId":"9007199254740993","executableId":"58","executableGuid":"77777777-7777-7777-7777-777777777777","packageName":"SyntheticChild.dtsx","packagePath":"\\Package\\SyntheticLeaf[9]","executionPath":"\\SyntheticRoot\\SyntheticLoop[1]\\SyntheticCall\\SyntheticChild\\SyntheticLeaf[9]","startTime":"2026-01-01T00:00:00Z","endTime":"2026-01-01T00:00:01Z","durationMs":10,"executionResult":0},{"statisticsId":"9","executionId":"9007199254740993","executableId":"59","executableGuid":"66666666-6666-6666-6666-666666666666","packageName":"SyntheticRoot.dtsx","packagePath":"\\Package.EventHandlers[OnPreExecute]\\SyntheticBody","executionPath":"\\SyntheticRoot\\OnPreExecute\\SyntheticBody","startTime":"2026-0