BEGIN TRY
 DECLARE @Case int=0,@M nvarchar(max),@C nvarchar(max),@Expected varchar(40),@Mapped int,@Invocations int,@Limit int,@X bit=CASE WHEN @@OPTIONS&16384=16384 THEN 1 ELSE 0 END;
 WHILE @Case<37
 BEGIN
  SELECT @M=@Models,@C=@Capture,@Expected='SCOPE_CAPTURE_BOUND',@Mapped=10,@Invocations=3,@Limit=1000;
  IF @Case=1 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[3].executionPath',N'\SyntheticRoot\SyntheticCall\SyntheticChild\SyntheticLeaf[9] ');SET @Mapped=9;END;
  IF @Case=2 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[5].executionPath',N'\SyntheticRoot\SyntheticLoop[01]\SyntheticCall');SELECT @Mapped=7,@Invocations=2;END;
  IF @Case=3 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[2].packageName','SyntheticRoot.dtsx');SELECT @Mapped=8,@Invocations=2;END;
  IF @Case=4 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].callTarget','SyntheticMissing.dtsx');SELECT @Mapped=8,@Invocations=2;END;
  IF @Case=5 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].callTarget','SyntheticRoot.dtsx');SELECT @Mapped=8,@Invocations=2;END;
  IF @Case=6 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[1].identities.objects[1].dtsId','11111111-1111-1111-1111-111111111111');SELECT @Mapped=6,@Invocations=1;END;
  IF @Case=7 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[8].durationMs',-1);END;
  IF @Case=8 BEGIN SET @C=JSON_MODIFY(@C,'strict $.observations[8].durationMs',NULL);END;
  IF @Case=9 SET @Limit=1;
  IF @Case=10 SET @C=JSON_MODIFY(@C,'$.execution.executionStatus',2);
  IF @Case=11 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[4].eventName','OnError ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=12 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].parentId','pkg1 ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=13 BEGIN SET @M=JSON_MODIFY(@M,'$.version','1.0.0 ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=14 BEGIN SET @M=JSON_MODIFY(@M,'strict $.contract',NULL);SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=15 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].steps[0].counter','false');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=16 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].steps[0].text',REPLICATE(CONVERT(nvarchar(max),N'x'),4001));SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=17 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].scopeKind','HANDLER');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=18 BEGIN SET @M=JSON_MODIFY(@M,'$.packages[0].identities.objects[1].nodeId','exe1 ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=19 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[1].executionId','1');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=20 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[1].executableGuid',REPLICATE('1',100));SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=21 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[1].executableId','not-number');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=22 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[1].executionPath',REPLICATE(CONVERT(nvarchar(max),N'x'),4001));SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=23 BEGIN SET @C=JSON_MODIFY(@C,'$.execution.projectLsn','0');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=24 BEGIN SET @C=JSON_MODIFY(@C,'strict $.execution.sourceBindingSha256',NULL);SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=25 BEGIN SET @C=JSON_MODIFY(@C,'strict $.observations',NULL);SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=26 BEGIN SET @C=JSON_MODIFY(@C,'$.method','SSISDB_CURRENT_PROJECT_SCOPES_V1 ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=27 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[0].executionPath',N'\SyntheticRoot\Extra');SELECT @Mapped=0,@Invocations=0;END;
  IF @Case=28 BEGIN SET @C=JSON_MODIFY(@C,'$.observations[9].statisticsId','9');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=29 BEGIN SET @C=JSON_MODIFY(@C,'$.execution.packageFileName','SyntheticRoot.dtsx ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=35 BEGIN DECLARE @Duplicate nvarchar(max)=JSON_MODIFY(JSON_QUERY(@C,'$.observations[2]'),'$.statisticsId','11');SET @C=JSON_MODIFY(@C,'append $.observations',JSON_QUERY(@Duplicate));SELECT @Mapped=8,@Invocations=2;END;
  IF @Case=36 BEGIN SET @C=JSON_MODIFY(@C,'strict $.execution.packageFileName',NULL);SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  SET @C=JSON_MODIFY(@C,'$.modelSetSha256',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@M)),2));
  SET @Receipt=(SELECT 'ssis-local-scope-handover' contract,'1.0.0' version,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@M)),2) modelSetSha256,CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@C)),2) captureSha256,CONVERT(varchar(24),@Now,127)+'Z' issuedUtc,CONVERT(varchar(24),DATEADD(hour,1,@Now),127)+'Z' expiresUtc FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
  IF @Case=30 BEGIN SET @Receipt=JSON_MODIFY(@Receipt,'$.expiresUtc','2020-01-01T00:00:00Z');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=31 BEGIN SET @Receipt=JSON_MODIFY(@Receipt,'$.captureSha256',REPLICATE('0',64));SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=32 BEGIN SET @Receipt=JSON_MODIFY(@Receipt,'strict $.issuedUtc',NULL);SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=33 BEGIN SET @Receipt=JSON_MODIFY(@Receipt,'$.contract','ssis-local-scope-handover ');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Case=34 BEGIN SET @C=REPLACE(@C,N'"loggingLevel":3',N'"loggingLevel":3,"loggingLevel":3');SET @Expected='SCOPE_BINDING_UNPROVEN';END;
  IF @Created=0 BEGIN EXEC sys.sp_addextendedproperty @name=@Name,@value=@Receipt,@level0type=N'SCHEMA',@level0name=N'monitor',@level1type=N'PROCEDURE',@level1name=N'USP_SsisPackageModelAnalysis';SET @Created=1;END;
  ELSE EXEC sys.sp_updateextendedproperty @name=@Name,@value=@Receipt,@level0type=N'SCHEMA',@level0name=N'monitor',@level1type=N'PROCEDURE',@level1name=N'USP_SsisPackageModelAnalysis';
  SET LOCK_TIMEOUT 1234;SET XACT_ABORT ON;
  EXEC monitor.USP_SsisPackageModelAnalysis @IncludeExecutionScopes=1,@ProjectModelsJson=@M,@ScopeSnapshotJson=@C,@ScopeHandoverId=@Id,@ExecutionId=9007199254740993,@MaxZeilen=@Limit,@ResultSetArt='NONE',@JsonErzeugen=1,@Json=@Json OUTPUT,@StatusCodeOut=@Status OUTPUT;
  IF @@LOCK_TIMEOUT<>1234 THROW 57901,N'SCOPE_CALLER_LOCK_TIMEOUT_CHANGED',1;
  IF @@OPTIONS&16384<>16384 THROW 57901,N'SCOPE_CALLER_XACT_ABORT_CHANGED',1;
  IF @X=0 SET XACT_ABORT OFF;
  IF @Status<>@Expected BEGIN DECLARE @Failure nvarchar(2048)=N'SCOPE_RECEIVER_CASE_'+CONVERT(nvarchar(10),@Case)+N'_'+COALESCE(JSON_VALUE(@Json,'$.scopeBinding[0].ReasonCode'),@Status);THROW 57901,@Failure,1;END;
  IF @Expected='SCOPE_CAPTURE_BOUND'
  BEGIN
   IF TRY_CONVERT(int,JSON_VALUE(@Json,'$.scopeCoverage[0].MappedStatisticsCount'))<>@Mapped OR TRY_CONVERT(int,JSON_VALUE(@Json,'$.scopeCoverage[0].InvocationCount'))<>@Invocations THROW 57901,N'SCOPE_COUNTS_INCORRECT',1;
   IF EXISTS(SELECT 1 FROM OPENJSON(@Json,'$.handlerActivity') WITH([cause] varchar(32) '$.CausalityStatus',[trigger] bigint '$.TriggerEventMessageId') WHERE [cause]<>'UNPROVEN' OR [trigger] IS NOT NULL) THROW 57901,N'SCOPE_HANDLER_CAUSE_INVENTED',1;
   IF @Case=0 AND JSON_VALUE(@Json,'$.scopeObservations[0].SourceKind') IS NULL THROW 57901,N'SCOPE_RAW_SOURCE_IDENTITY_LOST',1;
   IF @Case=0 AND ((SELECT COUNT(*) FROM OPENJSON(@Json,'$.handlerActivity'))<>3 OR (SELECT COUNT(*) FROM OPENJSON(@Json,'$.packageScopes'))<>2) THROW 57901,N'SCOPE_REPEATED_HANDLER_OR_SHARED_PACKAGE_GUID_LOST',1;
   IF @Case=9 AND (JSON_VALUE(@Json,'$.scopeCoverage[0].OutputTruncated')<>'true' OR (SELECT COUNT(*) FROM OPENJSON(@Json,'$.scopeObservations'))<>1) THROW 57901,N'SCOPE_LIMIT_DAMAGED_COUNTS',1;
   IF @Case IN(7,8) AND EXISTS(SELECT 1 FROM OPENJSON(@Json,'$.scopeObjectSummary') WITH([p] varchar(16) '$.PackageKey',[n] varchar(128) '$.ModelNodeId',[d] bigint '$.InclusiveObservedDurationMs') WHERE [p]='p1' AND [n]='exe5' AND [d] IS NOT NULL) THROW 57901,N'SCOPE_UNKNOWN_DURATION_REPLACED',1;
  END;
  SET @Case+=1;
 END;
 -- Leere Seed-Ziele sind der öffentliche TABLE-Vertrag. Vollständige Schemaanpassung vor dynamischem Lesen.
 CREATE TABLE #ScopeBinding([Seed] int);CREATE TABLE #ScopePackages([Seed] int);CREATE TABLE #ScopeInvocations([Seed] int);CREATE TABLE #ScopeObservations([Seed] int);CREATE TABLE #ScopeHandlers([Seed] int);CREATE TABLE #ScopeSummary([Seed] int);CREATE TABLE #ScopeCoverage([Seed] int);
 -- Letzten unveränderten Capture erneut korrekt attestieren.
 SET @C=JSON_MODIFY(@Capture,'$.modelSetSha256',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@Models)),2));
 SET @Receipt=JSON_MODIFY(JSON_MODIFY(@Receipt,'$.contract','ssis-local-scope-handover'),'$.captureSha256',CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@C)),2));
 EXEC sys.sp_updateextendedproperty @name=@Name,@value=@Receipt,@level0type=N'SCHEMA',@level0name=N'monitor',@level1type=N'PROCEDURE',@level1name=N'USP_SsisPackageModelAnalysis';
 EXEC monitor.USP_SsisPackageModelAnalysis @IncludeExecutionScopes=1,@ProjectModelsJson=@Models,@ScopeSnapshotJson=@C,@ScopeHandoverId=@Id,@ExecutionId=9007199254740993,@ResultSetArt='TABLE',@ResultTablesJson=N'{"scopeBinding":"#ScopeBinding","packageScopes":"#ScopePackages","packageInvocations":"#ScopeInvocations","scopeObservations":"#ScopeObservations","handlerActivity":"#ScopeHandlers","scopeObjectSummary":"#ScopeSummary","scopeCoverage":"#ScopeCoverage"}',@JsonErzeugen=1,@Json=@Json OUTPUT,@StatusCodeOut=@Status OUTPUT;
